from prettytable import PrettyTable


def table():
    t = PrettyTable()
    t.field_names = ['Name', 'Age', 'City']
    t.add_row(['Alice', 25, 'New York'])
    return t


def reproduce_report():
    t = table()
    t.none_format = 'N/A'
    t.sortby = 'Name'
    t.header = True
    print(t.get_string())


def probe_options():
    cases = [
        ('sortby', 'Name'),
        ('header', True),
        ('border', False),
        ('padding_width', 0),
        ('left_padding_width', 0),
        ('right_padding_width', 0),
        ('start', 0),
        ('attributes', {'class': 'prettytable'}),
        ('sort_key', lambda row: row[0]),
        ('none_format', 'N/A'),
        ('header_style', 'upper'),
    ]
    for option, value in cases:
        for method in ('setter', 'constructor', 'get_string'):
            try:
                if method == 'constructor':
                    t = PrettyTable(['Name', 'Age', 'City'], **{option: value})
                    t.add_row(['Alice', 25, 'New York'])
                else:
                    t = table()
                if method == 'setter':
                    setattr(t, option, value)
                kwargs = {option: value} if method == 'get_string' else {}
                result = t.get_string(**kwargs)
                if option == 'sort_key' and method == 'setter':
                    assert t.sort_key is value, 'sort_key setter discarded its value'
                assert 'Alice' in result
                print(f'PASS {method}: {option}')
            except Exception as error:
                print(f'FAIL {method}: {option}: {type(error).__name__}: {error}')


if __name__ == '__main__':
    try:
        reproduce_report()
    except Exception as error:
        print(f'Reported example fails: {type(error).__name__}: {error}')
    probe_options()
